ep_order_finalize.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let orderId = str(body.orderId ?? req.orderId ?? "").trim();

let orders = vdb.collection("orders");
let rows = [];
if (orderId != "") {
  let lookup = orders.find({orderId: {$eq: orderId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = orders.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No order is available to finalize"};
}

let order = rows[0];
orderId = str(order.orderId ?? orderId).trim();
let previousStatus = str(order.status ?? "PENDING").upper();
if (previousStatus == "FINALIZED" || previousStatus == "COMPLETED") {
  return {ok: true, orderId: orderId, updated: false, alreadyFinalized: true, status: previousStatus};
}
if (previousStatus == "CANCELLED") {
  return {ok: false, statusCode: 409, reason: "Cancelled orders cannot be finalized", orderId: orderId, status: previousStatus};
}

let nowTs = datetime.now().isoformat();
let shipping = type(order.shipping) == "object" ? order.shipping : {};
let nextShipping = {
  city: shipping.city ?? "",
  postalCode: shipping.postalCode ?? "",
  finalizedAt: nowTs,
  finalizedBy: actor
};
let updatePayload = {
  status: "FINALIZED",
  shipping: nextShipping,
  finalizedAt: nowTs,
  finalizedBy: actor
};

if (dryRun) {
  return {ok: true, dryRun: true, orderId: orderId, previousStatus: previousStatus, nextStatus: "FINALIZED", update: updatePayload};
}

let updateRes = orders.update({orderId: {$eq: orderId}}, updatePayload);
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to finalize order", orderId: orderId, result: updateRes};
}

let events = vdb.collection("order_events");
let eventId = crypto.uuid();
let eventRes = events.insert({
  eventId: eventId,
  orderId: orderId,
  action: "finalize",
  previousStatus: previousStatus,
  nextStatus: "FINALIZED",
  actor: actor,
  createdAt: nowTs
});

return {
  ok: true,
  orderId: orderId,
  previousStatus: previousStatus,
  nextStatus: "FINALIZED",
  updated: true,
  finalizedAt: nowTs,
  eventId: eventId,
  eventRecorded: eventRes.ok ?? false,
  result: updateRes
};

